const activeLoopStart = computed({ get: () => activeLoopRegion.value?.start ?? selectedAudio.value?.settings.audioSettings.loopStart ?? 0, set: value => { if (activeLoopRegion.value) activeLoopRegion.value.start = value; else if (selectedAudio.value) selectedAudio.value.settings.audioSettings.loopStart = value } })
const activeLoopEnd = computed({ get: () => activeLoopRegion.value?.end ?? selectedAudio.value?.settings.audioSettings.loopEnd ?? 0, set: value => { if (activeLoopRegion.value) activeLoopRegion.value.end = value; else if (selectedAudio.value) selectedAudio.value.settings.audioSettings.loopEnd = value } })
const themeAccent = computed({ get: () => String(themeDraft.value?.variables.accent ?? '#4f96ff'), set: value => { if (themeDraft.value) themeDraft.value.variables.accent = value } })
const themeSurface = computed({ get: () => String(themeDraft.value?.variables.surface ?? '#232934'), set: value => { if (themeDraft.value) themeDraft.value.variables.surface = value } })
